@page "/catalog"
@using sv_743f3eb7c9914722ac91dd4e2c0b1c08.Models
@using sv_743f3eb7c9914722ac91dd4e2c0b1c08.Components.Pages.Catalog
@inject IProductService ProductService
@rendermode InteractiveServer

<PageTitle>Product Catalog</PageTitle>

<h3 class="mb-3">Product Catalog</h3>

<div class="row">
    @* Left Sidebar — Filters *@
    <div class="col-md-3">
        <div class="border rounded">
            @if (_categoriesLoading)
            {
                <div class="p-3 text-center">
                    <div class="spinner-border spinner-border-sm" role="status"></div>
                    <span class="ms-2">Loading filters…</span>
                </div>
            }
            else
            {
                <CatalogFilters Categories="_categories"
                                CurrentFilter="_filter"
                                OnFiltersApplied="HandleFiltersApplied" />
            }
        </div>
    </div>

    @* Main Content — Products *@
    <div class="col-md-9">
        @if (_error is not null)
        {
            <div class="alert alert-danger" role="alert">
                <strong>Error:</strong> @_error
                <button class="btn btn-sm btn-outline-danger ms-2" @onclick="LoadProductsAsync">Retry</button>
            </div>
        }
        else
        {
            <CatalogToolbar SortBy="@_sortBy"
                            TotalCount="@_totalCount"
                            Page="@_currentPage"
                            PageSize="@PageSize"
                            OnSortChanged="HandleSortChanged" />

            @if (_loading)
            {
                <div class="text-center py-5">
                    <div class="spinner-border" role="status">
                        <span class="visually-hidden">Loading…</span>
                    </div>
                    <p class="mt-2 text-muted">Loading products…</p>
                </div>
            }
            else if (_products.Count == 0)
            {
                <div class="text-center py-5">
                    <p class="text-muted fs-5">No products match your criteria.</p>
                    <button class="btn btn-outline-primary" @onclick="ClearAndReload">Clear Filters</button>
                </div>
            }
            else
            {
                <ProductGrid Products="_products"
                             OnProductSelected="HandleProductSelected"
                             OnAddToCart="HandleAddToCart" />

                @if (_totalPages > 1)
                {
                    <div class="mt-4">
                        <CatalogPagination CurrentPage="_currentPage"
                                           TotalPages="_totalPages"
                                           OnPageChanged="HandlePageChanged" />
                    </div>
                }
            }
        }
    </div>
</div>

